//! Small helpers for emitting Rust and Starlark source text.
//!
//! Stable infrastructure shared by every profile version (audit Q4): the bytes
//! of every published profile depend on these functions, so each is frozen. A
//! version that needs different text gets a new function; these never change.
//! The tests below pin their output, edge cases included.

/// The first line of every generated file.
pub fn generated_marker(profile: &str) -> String {
    format!(
        "// @generated by L2R ({profile}). Do not edit: change the architecture model or the\n\
         // Lean specification, then re-plan, re-approve and regenerate.\n"
    )
}

/// True when `content` begins with the `@generated by L2R (` marker that every
/// generated file carries on its first line (as a `//` or `#` comment).
///
/// This is the one definition shared by the planner, which refuses to plan a
/// generated file without it, and by the writer, which never deletes a file that
/// lacks it, whatever the (untrusted) lock claims.
pub fn declares_generated(content: &[u8]) -> bool {
    [
        b"// @generated by L2R (".as_slice(),
        b"# @generated by L2R (".as_slice(),
    ]
    .iter()
    .any(|marker| content.starts_with(marker))
}

/// Renders `text` as `//!` inner doc lines (blank lines preserved).
pub fn inner_doc(text: &str) -> String {
    prefixed("//!", text)
}

fn prefixed(prefix: &str, text: &str) -> String {
    let mut out = String::new();
    for line in text.lines() {
        if line.is_empty() {
            out.push_str(prefix);
        } else {
            out.push_str(prefix);
            out.push(' ');
            out.push_str(line);
        }
        out.push('\n');
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn doc_lines_keep_blank_lines_without_trailing_spaces() {
        assert_eq!(inner_doc("a\n\nb"), "//! a\n//!\n//! b\n");
    }

    #[test]
    fn doc_lines_are_frozen_on_edge_cases() {
        assert_eq!(inner_doc(""), "");
        assert_eq!(inner_doc("a\n"), "//! a\n");
        assert_eq!(inner_doc("a\n\n"), "//! a\n//!\n");
        assert_eq!(inner_doc("\na"), "//!\n//! a\n");
        assert_eq!(inner_doc("  indented"), "//!   indented\n");
        assert_eq!(inner_doc("tab\tand ä"), "//! tab\tand ä\n");
        assert_eq!(inner_doc("a\r\nb"), "//! a\n//! b\n");
    }

    #[test]
    fn the_generated_marker_is_frozen() {
        assert_eq!(
            generated_marker("composite/v0"),
            "// @generated by L2R (composite/v0). Do not edit: change the architecture model or the\n\
             // Lean specification, then re-plan, re-approve and regenerate.\n"
        );
        assert!(declares_generated(generated_marker("x").as_bytes()));
        assert!(declares_generated(b"# @generated by L2R (crate-root/v0)."));
        assert!(!declares_generated(b" // @generated by L2R ("));
    }
}
